theorem buchstab_lower_integral_sound {δ s : ℝ}
    (hδ : 0 < δ) (hδhi : δ ≤ 1 / 10) (hs : 2 ≤ s) (hs5 : s ≤ 5) :
    (∫ u in (s-1)..5, H δ u / u) ≤ h δ s

theorem buchstab_upper_integral_sound {δ s : ℝ}
    (hδ : 0 < δ) (hδhi : δ ≤ 1 / 10) (hs : 2 ≤ s) (hs5 : s ≤ 5) :
    (∫ u in (max 2 (s-1))..5, h δ u / u) ≤ H δ s
